import{_ as o,W as i,s as c,u as l,ah as d,I as n,w as s,Z as a,A as t}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const k=JSON.parse('{"title":"如何在 Linux 上使用 pbcopy 和 pbpaste 命令 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上使用 pbcopy 和 pbpaste 命令 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Linux 上使用 pbcopy 和 pbpaste 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上使用 pbcopy 和 pbpaste 命令 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180731 How To Use Pbcopy And Pbpaste Commands On Linux","title":"如何在 Linux 上使用 pbcopy 和 pbpaste 命令","tag":"201808"},"relativePath":"201808/20180731 How To Use Pbcopy And Pbpaste Commands On Linux.md","filePath":"[post].md"}'),b={name:"201808/20180731 How To Use Pbcopy And Pbpaste Commands On Linux.md"};function u(h,p,r,g,x,m){const e=i("Link");return l(),c("div",null,[p[15]||(p[15]=d(`<h1 id="如何在-linux-上使用-pbcopy-和-pbpaste-命令" tabindex="-1">如何在 Linux 上使用 pbcopy 和 pbpaste 命令 <a class="header-anchor" href="#如何在-linux-上使用-pbcopy-和-pbpaste-命令" aria-label="Permalink to 如何在 Linux 上使用 pbcopy 和 pbpaste 命令">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/07/Pbcopy-And-Pbpaste-Commands-720x340.png" alt=""></p><p>由于 Linux 和 Mac OS X 是基于 *Nix 的系统，因此许多命令可以在两个平台上运行。但是，某些命令可能在两个平台上都没有，比如 <code>pbcopy</code> 和 <code>pbpast</code>。这些命令仅在 Mac OS X 平台上可用。<code>pbcopy</code> 命令将标准输入复制到剪贴板。然后，你可以在任何地方使用 <code>pbpaste</code> 命令粘贴剪贴板内容。当然，上述命令可能有一些 Linux 替代品，例如 <code>xclip</code>。 <code>xclip</code> 与 <code>pbcopy</code> 完全相同。但是，从 Mac OS 切换到 Linux 的发行版的人将会找不到这两个命令，不过仍然想使用它们。别担心！这个简短的教程描述了如何在 Linux 上使用 <code>pbcopy</code> 和 <code>pbpaste</code> 命令。</p><h3 id="安装-xclip-xsel" tabindex="-1">安装 xclip / xsel <a class="header-anchor" href="#安装-xclip-xsel" aria-label="Permalink to 安装 xclip / xsel">​</a></h3><p>就像我已经说过的那样，Linux 中没有 <code>pbcopy</code> 和 <code>pbpaste</code> 命令。但是，我们可以通过 shell 别名使用 xclip 和/或 xsel 命令复制 <code>pbcopy</code> 和 <code>pbpaste</code> 命令的功能。xclip 和 xsel 包存在于大多数 Linux 发行版的默认存储库中。请注意，你无需安装这两个程序。只需安装上述任何一个程序即可。</p><p>要在 Arch Linux 及其衍生产版上安装它们，请运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo pacman xclip xsel</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf xclip xsel</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo apt install xclip xsel</span></span></code></pre></div><p>安装后，你需要为 <code>pbcopy</code> 和 <code>pbpaste</code> 命令创建别名。为此，请编辑 <code>~/.bashrc</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vi ~/.bashrc</span></span></code></pre></div><p>如果要使用 xclip，请粘贴以下行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>alias pbcopy=&#39;xclip -selection clipboard&#39;</span></span>
<span class="line"><span>alias pbpaste=&#39;xclip -selection clipboard -o&#39;</span></span></code></pre></div><p>如果要使用 xsel，请在 <code>~/.bashrc</code> 中粘贴以下行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>alias pbcopy=&#39;xsel --clipboard --input&#39;</span></span>
<span class="line"><span>alias pbpaste=&#39;xsel --clipboard --output&#39;</span></span></code></pre></div><p>保存并关闭文件。</p><p>接下来，运行以下命令以更新 <code>~/.bashrc</code> 中的更改。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>ZSH 用户将上述行粘贴到 <code>~/.zshrc</code> 中。</p><h3 id="在-linux-上使用-pbcopy-和-pbpaste-命令" tabindex="-1">在 Linux 上使用 pbcopy 和 pbpaste 命令 <a class="header-anchor" href="#在-linux-上使用-pbcopy-和-pbpaste-命令" aria-label="Permalink to 在 Linux 上使用 pbcopy 和 pbpaste 命令">​</a></h3><p>让我们看一些例子。</p><p><code>pbcopy</code> 命令将文本从 stdin 复制到剪贴板缓冲区。例如，看看下面的例子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo &quot;Welcome To OSTechNix!&quot; | pbcopy</span></span></code></pre></div><p>上面的命令会将文本 “Welcome to OSTechNix” 复制到剪贴板中。你可以稍后访问此内容并使用如下所示的 <code>pbpaste</code> 命令将其粘贴到任何位置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo \`pbpaste\`</span></span>
<span class="line"><span>Welcome To OSTechNix!</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/07/pbcopy-and-pbpaste-commands-in-action.png" alt=""></p><p>以下是一些其他例子。</p><p>我有一个名为 <code>file.txt</code> 的文件，其中包含以下内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat file.txt</span></span>
<span class="line"><span>Welcome To OSTechNix!</span></span></code></pre></div><p>你可以直接将文件内容复制到剪贴板中，如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pbcopy &lt; file.txt</span></span></code></pre></div><p>现在，只要你用其他文件的内容更新了剪切板，那么剪切板中的内容就可用了。</p><p>要从剪贴板检索内容，只需输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pbpaste</span></span>
<span class="line"><span>Welcome To OSTechNix!</span></span></code></pre></div><p>你还可以使用管道字符将任何 Linux 命令的输出发送到剪贴板。看看下面的例子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ps aux | pbcopy</span></span></code></pre></div><p>现在，输入 <code>pbpaste</code> 命令以显示剪贴板中 <code>ps aux</code> 命令的输出。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pbpaste</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/07/pbcopy-and-pbpaste-commands-2.png" alt=""></p><p>使用 <code>pbcopy</code> 和 <code>pbpaste</code> 命令可以做更多的事情。我希望你现在对这些命令有一个基本的想法。</p><p>就是这些了。还有更好的东西。敬请关注！</p><p>干杯!</p><hr>`,45)),n("p",null,[p[1]||(p[1]=s("via: ")),a(e,{href:"https://www.ostechnix.com/how-to-use-pbcopy-and-pbpaste-commands-on-linux/"},{default:t(()=>p[0]||(p[0]=[s("https://www.ostechnix.com/how-to-use-pbcopy-and-pbpaste-commands-on-linux/")])),_:1})]),n("p",null,[p[6]||(p[6]=s("作者：")),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>p[2]||(p[2]=[s("SK")])),_:1}),p[7]||(p[7]=s(" 选题：")),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>p[3]||(p[3]=[s("lujun9972")])),_:1}),p[8]||(p[8]=s(" 译者：")),a(e,{href:"https://github.com/geekpi"},{default:t(()=>p[4]||(p[4]=[s("geekpi")])),_:1}),p[9]||(p[9]=s(" 校对：")),a(e,{href:"https://github.com/wxy"},{default:t(()=>p[5]||(p[5]=[s("wxy")])),_:1})]),n("p",null,[p[12]||(p[12]=s("本文由 ")),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>p[10]||(p[10]=[s("LCTT")])),_:1}),p[13]||(p[13]=s(" 原创编译，")),a(e,{href:"https://linux.cn/"},{default:t(()=>p[11]||(p[11]=[s("Linux中国")])),_:1}),p[14]||(p[14]=s(" 荣誉推出"))])])}const C=o(b,[["render",u]]);export